                *error = "Moved QObject properties support only null/bool/int/float/string/array values.";
            }
            return false;
        }

        qt_qthreadruntime_object_property property;
        property.key.assign(ZSTR_VAL(key), ZSTR_LEN(key));
        property.value = std::move(value);
        out->push_back(std::move(property));
    } ZEND_HASH_FOREACH_END();

    return true;
}

static bool qt_qthreadruntime_restore_object_properties(zend_object *object, const std::vector<qt_qthreadruntime_object_property> &properties, std::string *error)
{
    if (object == nullptr) {
        if (error != nullptr) {
            *error = "Invalid moved object restore target.";
        }
        return false;
    }

    for (const qt_qthreadruntime_object_property &property : properties) {
        zval value;
        ZVAL_NULL(&value);
        if (!qt_qthreadruntime_value_to_zval(property.value, &value)) {
            if (error != nullptr) {
                *error = "Failed to restore moved QObject property value.";
            }
            return false;
        }

        zend_string *key = zend_string_init(property.key.data(), property.key.size(), 0);
        zend_update_property_ex(object->ce, object, key, &value);
        zend_string_release(key);
        zval_ptr_dtor(&value);
        if (EG(exception) != NULL) {
            if (error != nullptr) {
                *error = "Failed to restore moved QObject property entry.";
            }
            return false;
        }
    }

    return true;
}

static bool qt_qthreadruntime_require_class_definition(const std::string &class_name, const std::string &class_file, zend_class_entry **out_ce, std::string *error)
{
    if (out_ce == nullptr) {
        if (error != nullptr) {
            *error = "Invalid moved class lookup target.";
        }
        return false;
    }

    *out_ce = nullptr;
    zend_string *name = zend_string_init(class_name.data(), class_name.size(), 0);
    zend_class_entry *ce = zend_lookup_class_ex(name, NULL, 0);
    if (ce == NULL && !class_file.empty()) {
        zend_string *file = zend_string_init(class_file.data(), class_file.size(), 0);
        zend_file_handle file_handle;
        zend_stream_init_filename_ex(&file_handle, file);
        zend_string_release(file);

        if (zend_execute_script(ZEND_REQUIRE_ONCE, NULL, &file_handle) != SUCCESS) {
            if (error != nullptr && error->empty()) {
                *error = "Failed to load moved QObject class definition on worker thread.";
            }
        }

        if (EG(exception) != NULL) {
            if (error != nullptr && error->empty()) {
                zval ex_zv;
                ZVAL_OBJ_COPY(&ex_zv, EG(exception));
                zend_clear_exception();
                zend_string *message = zval_get_string(&ex_zv);
                if (message != NULL) {
                    *error = std::string(ZSTR_VAL(message), ZSTR_LEN(message));
                    zend_string_release(message);
                } else {
                    *error = "Moved QObject class bootstrap raised an exception.";
                }
                zval_ptr_dtor(&ex_zv);
            } else if (EG(exception) != NULL) {
                zend_clear_exception();
            }
        }

        ce = zend_lookup_class_ex(name, NULL, 0);
    }
    zend_string_release(name);

    if (ce == NULL) {
        if (error != nullptr && error->empty()) {
            *error = "Moved QObject class is not available on worker thread.";
        }
        return false;
    }

    *out_ce = ce;
    return true;
}

static inline void qt_qthreadruntime_listener_clear(const std::shared_ptr<qt_qthreadruntime_listener_t> &listener)
{
    if (!listener) {
        return;
    }

    listener->fci.params = NULL;
    listener->fci.param_count = 0;
    listener->fci.retval = NULL;
    if (!Z_ISUNDEF(listener->fci.function_name)) {
        zval_ptr_dtor(&listener->fci.function_name);
        ZVAL_UNDEF(&listener->fci.function_name);
    }
}

static bool qt_qthreadruntime_listener_invoke(const std::shared_ptr<qt_qthreadruntime_listener_t> &listener, zval *arg)
{
    if (!listener || !qt_runtime_can_call_zend() || arg == NULL) {
        return false;
    }

    zval retval;
    ZVAL_NULL(&retval);

    zval *prev_params = listener->fci.params;
    uint32_t prev_param_count = listener->fci.param_count;
    zval *prev_retval = listener->fci.retval;

    listener->fci.params = arg;
    listener->fci.param_count = 1;
    listener->fci.retval = &retval;

    bool ok = zend_call_function(&listener->fci, &listener->fci_cache) == SUCCESS;
    listener->fci.params = prev_params;
    listener->fci.param_count = prev_param_count;
    listener->fci.retval = prev_retval;
    zval_ptr_dtor(&retval);

    return ok;
}

class qt_qthreadruntime_worker_thread final : public QThread {
public:
    explicit qt_qthreadruntime_worker_thread(std::weak_ptr<qt_qthreadruntime_state> state)
        : state_(std::move(state))
    {
    }

    void run() override;

private:
    std::weak_ptr<qt_qthreadruntime_state> state_;
};

class qt_qthreadruntime_state final : public std::enable_shared_from_this<qt_qthreadruntime_state> {
public:
    bool setBootstrapScript(const std::string &path, std::string *error)
    {
        if (error == nullptr) {
            return false;
        }

        std::lock_guard<std::mutex> lock(mutex_);
        if (running_) {
            *error = "Cannot change bootstrap script while worker runtime is running.";
            return false;
        }

        bootstrap_script_ = path;
        return true;
    }

    bool start()
    {
        std::lock_guard<std::mutex> lock(mutex_);
        if (running_) {
            return true;
        }

#if !defined(ZTS)
        return false;
#else
        qt_qthreadruntime_capture_request_snapshot(&owner_request_snapshot_);
        stopping_ = false;
        worker_bootstrap_failed_ = false;
        owner_event_drain_scheduled_.store(false, std::memory_order_release);
        worker_thread_ = std::make_unique<qt_qthreadruntime_worker_thread>(shared_from_this());
        worker_thread_->start();
        running_ = true;
        return true;
#endif
    }

    bool stop(zend_long timeout_ms)
    {
        std::vector<std::shared_ptr<qt_qthreadruntime_listener_t>> listeners_to_clear;

        std::unique_lock<std::mutex> lock(mutex_);
        if (!running_) {
            listeners_to_clear.reserve(listeners_by_id_.size());
            for (const auto &entry : listeners_by_id_) {
                listeners_to_clear.push_back(entry.second);
            }
            listeners_by_id_.clear();
            listener_ids_by_event_.clear();
            stats_listeners_registered_ = 0;
            lock.unlock();
            for (const auto &listener : listeners_to_clear) {
                qt_qthreadruntime_listener_clear(listener);
            }
            return true;
        }

        stopping_ = true;
        dropEventQueuesLocked(true);
        while (!queue_.empty()) {
            std::shared_ptr<qt_qthreadruntime_job> job = queue_.front();
            queue_.pop_front();
            if (!job) {
                continue;
            }

            job->canceled.store(true, std::memory_order_release);
            jobs_.erase(job->id);
            qt_qthreadruntime_result canceled_result;
            canceled_result.ready = true;
            canceled_result.success = false;
            canceled_result.canceled = true;
            results_[job->id] = std::move(canceled_result);
            stats_canceled_++;
            qt_qthreadruntime_total_canceled.fetch_add(1, std::memory_order_acq_rel);
            inbound_events_by_job_.erase(job->id);
        }

        result_cv_.notify_all();
        inbound_cv_.notify_all();
        job_cv_.notify_all();
        lock.unlock();

        bool stopped = true;
        if (worker_thread_ != nullptr && worker_thread_->isRunning()) {
            unsigned long wait_ms = timeout_ms > 0 ? (unsigned long) timeout_ms : 0UL;
            if (!worker_thread_->wait(wait_ms)) {
                worker_thread_->requestInterruption();
                job_cv_.notify_all();
                stopped = worker_thread_->wait(500);
            }
        }

        lock.lock();
        running_ = false;
        worker_thread_.reset();
        listeners_to_clear.reserve(listeners_by_id_.size());
        for (const auto &entry : listeners_by_id_) {
            listeners_to_clear.push_back(entry.second);
        }
        listeners_by_id_.clear();
        listener_ids_by_event_.clear();
        stats_listeners_registered_ = 0;
        lock.unlock();

        for (const auto &listener : listeners_to_clear) {
            qt_qthreadruntime_listener_clear(listener);
        }

        return stopped;
    }

    bool isRunning() const
    {
        std::lock_guard<std::mutex> lock(mutex_);
        return running_;
    }

    bool submit(std::string callable_payload, std::string args_payload, uint64_t *job_id, std::string *error)
    {
        if (job_id == nullptr || error == nullptr) {
            return false;
        }

        std::lock_guard<std::mutex> lock(mutex_);
        if (!running_) {
            *error = "Worker runtime is not started.";
            return false;
        }

        if (stopping_) {
            stats_rejected_stopping_++;
            qt_qthreadruntime_total_rejected_stopping.fetch_add(1, std::memory_order_acq_rel);
            *error = "Worker runtime is stopping.";
            return false;
        }

        if (queue_.size() >= max_queue_depth_) {
            stats_rejected_full_++;
            qt_qthreadruntime_total_rejected_full.fetch_add(1, std::memory_order_acq_rel);
            *error = "Worker runtime queue is full.";
            return false;
        }

        auto job = std::make_shared<qt_qthreadruntime_job>();
        job->id = next_job_id_++;
        job->callable_payload = std::move(callable_payload);
        job->args_payload = std::move(args_payload);

        jobs_[job->id] = job;
        queue_.push_back(job);
        inbound_events_by_job_.emplace(job->id, std::deque<qt_qthreadruntime_event_message>());
        stats_enqueued_++;
        qt_qthreadruntime_total_enqueued.fetch_add(1, std::memory_order_acq_rel);
        *job_id = job->id;

        job_cv_.notify_one();
        return true;
    }

    bool cancel(uint64_t job_id)
    {
        std::lock_guard<std::mutex> lock(mutex_);
        auto it = jobs_.find(job_id);
        if (it == jobs_.end()) {
            return false;
        }

        it->second->canceled.store(true, std::memory_order_release);
        stats_canceled_++;
        return true;
    }

    qt_qthreadruntime_await_status await(uint64_t job_id, zend_long timeout_ms, qt_qthreadruntime_result *result)
    {
        if (result == nullptr) {
            return qt_qthreadruntime_await_status::unknown;
        }

        std::unique_lock<std::mutex> lock(mutex_);
        auto done = [this, job_id]() -> bool {
            return results_.find(job_id) != results_.end();
        };

        if (timeout_ms <= 0) {
            result_cv_.wait(lock, done);
        } else if (!result_cv_.wait_for(lock, std::chrono::milliseconds(timeout_ms), done)) {
            stats_timeouts_++;
            qt_qthreadruntime_total_timeouts.fetch_add(1, std::memory_order_acq_rel);
            return qt_qthreadruntime_await_status::timeout;
        }

        auto result_it = results_.find(job_id);
        if (result_it == results_.end()) {
            return qt_qthreadruntime_await_status::unknown;
        }

        *result = std::move(result_it->second);
        results_.erase(result_it);
        return qt_qthreadruntime_await_status::ready;
    }

    bool addListener(const std::string &event_name, zval *listener, uint64_t *listener_id, std::string *error)
    {
        if (listener == nullptr || listener_id == nullptr || error == nullptr) {
            return false;
        }

        if (!qt_runtime_can_call_zend()) {
            *error = "Listeners can only be registered from owner request thread.";
            return false;
        }

        std::shared_ptr<qt_qthreadruntime_listener_t> handle = std::make_shared<qt_qthreadruntime_listener_t>();
        memset(&handle->fci, 0, sizeof(handle->fci));
        memset(&handle->fci_cache, 0, sizeof(handle->fci_cache));
        ZVAL_UNDEF(&handle->fci.function_name);

        char *fci_error = NULL;
        if (zend_fcall_info_init(listener, 0, &handle->fci, &handle->fci_cache, NULL, &fci_error) != SUCCESS) {
            if (fci_error != NULL) {
                *error = std::string("Invalid listener: ") + fci_error;
                efree(fci_error);
            } else {
                *error = "Invalid listener.";
            }
            return false;
        }
        Z_TRY_ADDREF(handle->fci.function_name);

        std::lock_guard<std::mutex> lock(mutex_);
        if (stopping_) {
            qt_qthreadruntime_listener_clear(handle);
            *error = "Worker runtime is stopping.";
            return false;
        }

        handle->id = next_listener_id_++;
        handle->event_name = event_name;

        listeners_by_id_[handle->id] = handle;
        listener_ids_by_event_[event_name].push_back(handle->id);
        stats_listeners_registered_ = listeners_by_id_.size();

        *listener_id = handle->id;
        return true;
    }

    bool removeListener(uint64_t listener_id)
    {
        std::shared_ptr<qt_qthreadruntime_listener_t> handle;
        {
            std::lock_guard<std::mutex> lock(mutex_);
            auto it = listeners_by_id_.find(listener_id);
            if (it == listeners_by_id_.end()) {
                return false;
            }

            handle = it->second;
            listeners_by_id_.erase(it);
            auto event_it = listener_ids_by_event_.find(handle->event_name);
            if (event_it != listener_ids_by_event_.end()) {
                std::vector<uint64_t> &ids = event_it->second;
                ids.erase(std::remove(ids.begin(), ids.end(), listener_id), ids.end());
                if (ids.empty()) {
                    listener_ids_by_event_.erase(event_it);
                }
            }
            stats_listeners_registered_ = listeners_by_id_.size();
        }

        qt_qthreadruntime_listener_clear(handle);
        return true;
    }

    zend_long drainEvents(zend_long max_items)
    {
        if (!qt_runtime_can_call_zend() || max_items == 0) {
            return 0;
        }

        zend_long processed = 0;
        while (max_items < 0 || processed < max_items) {
            qt_qthreadruntime_event_message message;
            std::vector<std::shared_ptr<qt_qthreadruntime_listener_t>> listeners;
            {
                std::lock_guard<std::mutex> lock(mutex_);
                if (outbound_events_.empty()) {
                    break;
                }

                message = std::move(outbound_events_.front());
                outbound_events_.pop_front();
                stats_events_out_drained_++;
                qt_qthreadruntime_total_events_out_drained.fetch_add(1, std::memory_order_acq_rel);

                auto event_it = listener_ids_by_event_.find(message.event_name);
                if (event_it != listener_ids_by_event_.end()) {
                    listeners.reserve(event_it->second.size());
                    for (uint64_t id : event_it->second) {
                        auto listener_it = listeners_by_id_.find(id);
                        if (listener_it != listeners_by_id_.end()
                            && listener_it->second
                            && (listener_it->second->task_token_filter == 0 || listener_it->second->task_token_filter == message.job_id)
                        ) {
                            listeners.push_back(listener_it->second);
                        }
                    }
                }
            }

            processed++;
            if (listeners.empty()) {
                continue;
            }

            zval payload;
            if (!qt_qthreadruntime_value_to_zval(message.payload, &payload)) {
                continue;
            }

            zval envelope;
            array_init(&envelope);
            add_assoc_stringl(&envelope, "event", message.event_name.data(), message.event_name.size());
            add_assoc_long(&envelope, "jobId", (zend_long) message.job_id);
            add_assoc_zval(&envelope, "payload", &payload);

            for (const std::shared_ptr<qt_qthreadruntime_listener_t> &listener : listeners) {
                if (!qt_qthreadruntime_listener_invoke(listener, &envelope) || EG(exception) != NULL) {
                    if (EG(exception) != NULL) {
                        zend_clear_exception();
                    }
                    stats_listener_dispatch_errors_++;
                    qt_qthreadruntime_total_listener_dispatch_errors.fetch_add(1, std::memory_order_acq_rel);
#if ZEND_DEBUG
                    php_error_docref(NULL, E_WARNING, "QThreadRuntime listener for event '%s' failed.", message.event_name.c_str());
#endif
                }
            }

            zval_ptr_dtor(&envelope);
        }

        {
            std::lock_guard<std::mutex> lock(mutex_);
            if (!outbound_events_.empty()) {
                scheduleOwnerEventDrain();
            }
        }

        return processed;
    }

    bool sendCommand(uint64_t job_id, const std::string &event_name, const qt_qthreadruntime_value &payload)
    {
        std::lock_guard<std::mutex> lock(mutex_);
        if (!running_ || stopping_) {
            stats_events_in_dropped_shutdown_++;
            qt_qthreadruntime_total_events_in_dropped_shutdown.fetch_add(1, std::memory_order_acq_rel);
            return false;
        }

        auto job_it = jobs_.find(job_id);
        if (job_it == jobs_.end()) {
            return false;
        }

        auto queue_it = inbound_events_by_job_.find(job_id);
        if (queue_it == inbound_events_by_job_.end()) {
            return false;
        }

        if (queue_it->second.size() >= max_event_in_queue_depth_) {
            stats_events_in_dropped_full_++;
            qt_qthreadruntime_total_events_in_dropped_full.fetch_add(1, std::memory_order_acq_rel);
            return false;
        }

        qt_qthreadruntime_event_message message;
        message.job_id = job_id;
        message.event_name = event_name;
        message.payload = payload;
        queue_it->second.push_back(std::move(message));
        stats_events_in_enqueued_++;
        qt_qthreadruntime_total_events_in_enqueued.fetch_add(1, std::memory_order_acq_rel);
        inbound_cv_.notify_all();
        return true;
    }

    bool publishFromWorker(uint64_t job_id, const std::string &event_name, const qt_qthreadruntime_value &payload)
    {
        std::lock_guard<std::mutex> lock(mutex_);
        if (stopping_) {
            stats_events_out_dropped_shutdown_++;
            qt_qthreadruntime_total_events_out_dropped_shutdown.fetch_add(1, std::memory_order_acq_rel);
            return false;
        }

        if (outbound_events_.size() >= max_event_out_queue_depth_) {
            stats_events_out_dropped_full_++;
            qt_qthreadruntime_total_events_out_dropped_full.fetch_add(1, std::memory_order_acq_rel);
            return false;
        }

        qt_qthreadruntime_event_message message;
        message.job_id = job_id;
        message.event_name = event_name;
        message.payload = payload;
        outbound_events_.push_back(std::move(message));
        stats_events_out_enqueued_++;
        qt_qthreadruntime_total_events_out_enqueued.fetch_add(1, std::memory_order_acq_rel);
        scheduleOwnerEventDrain();
        return true;
    }

    bool receiveForWorker(uint64_t job_id, zend_long timeout_ms, qt_qthreadruntime_event_message *message)
    {
        if (message == nullptr) {
            return false;
        }

        std::unique_lock<std::mutex> lock(mutex_);
        auto ready = [this, job_id]() -> bool {
            auto queue_it = inbound_events_by_job_.find(job_id);
            return stopping_ || (queue_it != inbound_events_by_job_.end() && !queue_it->second.empty());
        };

        if (timeout_ms <= 0) {
            inbound_cv_.wait(lock, ready);
        } else if (!inbound_cv_.wait_for(lock, std::chrono::milliseconds(timeout_ms), ready)) {
            return false;
        }

        if (stopping_) {
            return false;
        }

        auto queue_it = inbound_events_by_job_.find(job_id);
        if (queue_it == inbound_events_by_job_.end() || queue_it->second.empty()) {
            return false;
        }

        *message = std::move(queue_it->second.front());
        queue_it->second.pop_front();
        stats_events_in_drained_++;
        qt_qthreadruntime_total_events_in_drained.fetch_add(1, std::memory_order_acq_rel);
        return true;
    }

    void fillStats(zval *return_value) const
    {
        std::lock_guard<std::mutex> lock(mutex_);

        array_init(return_value);
        add_assoc_bool(return_value, "running", running_);
        add_assoc_long(return_value, "queued", (zend_long) queue_.size());
        add_assoc_long(return_value, "queue_max_depth", (zend_long) max_queue_depth_);
        add_assoc_long(return_value, "pending_results", (zend_long) results_.size());
        add_assoc_long(return_value, "enqueued", (zend_long) stats_enqueued_);
        add_assoc_long(return_value, "drained", (zend_long) stats_drained_);
        add_assoc_long(return_value, "canceled", (zend_long) stats_canceled_);
        add_assoc_long(return_value, "rejected_full", (zend_long) stats_rejected_full_);
        add_assoc_long(return_value, "rejected_stopping", (zend_long) stats_rejected_stopping_);
        add_assoc_long(return_value, "timeouts", (zend_long) stats_timeouts_);
        add_assoc_long(return_value, "worker_crash", (zend_long) stats_worker_crash_);
        add_assoc_bool(return_value, "worker_bootstrap_failed", worker_bootstrap_failed_);
        add_assoc_long(return_value, "listeners_registered", (zend_long) stats_listeners_registered_);
        add_assoc_long(return_value, "events_out_enqueued", (zend_long) stats_events_out_enqueued_);
        add_assoc_long(return_value, "events_out_drained", (zend_long) stats_events_out_drained_);
        add_assoc_long(return_value, "events_out_dropped_full", (zend_long) stats_events_out_dropped_full_);
        add_assoc_long(return_value, "events_out_dropped_shutdown", (zend_long) stats_events_out_dropped_shutdown_);
        add_assoc_long(return_value, "events_in_enqueued", (zend_long) stats_events_in_enqueued_);
        add_assoc_long(return_value, "events_in_drained", (zend_long) stats_events_in_drained_);
        add_assoc_long(return_value, "events_in_dropped_full", (zend_long) stats_events_in_dropped_full_);
        add_assoc_long(return_value, "events_in_dropped_shutdown", (zend_long) stats_events_in_dropped_shutdown_);
        add_assoc_long(return_value, "listener_dispatch_errors", (zend_long) stats_listener_dispatch_errors_);
    }

    void workerMain()
    {
#if !defined(ZTS)
        return;
#else
        if (!qt_qthreadruntime_prepare_worker_request(owner_request_snapshot_)) {
            std::lock_guard<std::mutex> lock(mutex_);
            worker_bootstrap_failed_ = true;
            running_ = false;
            stopping_ = true;
            return;
        }

        std::string bootstrap_script;
        {
            std::lock_guard<std::mutex> lock(mutex_);
            bootstrap_script = bootstrap_script_;
        }
        if (!bootstrap_script.empty()) {
            std::string bootstrap_error;
            if (!executeBootstrapScript(bootstrap_script, &bootstrap_error)) {
                std::lock_guard<std::mutex> lock(mutex_);
                worker_bootstrap_failed_ = true;
                running_ = false;
                stopping_ = true;
                qt_qthreadruntime_total_worker_crash.fetch_add(1, std::memory_order_acq_rel);
                qt_qthreadruntime_result failed;
                failed.ready = true;
                failed.success = false;
                failed.canceled = false;
                failed.error.class_name = "RuntimeException";
                failed.error.message = bootstrap_error.empty()
                    ? std::string("Worker bootstrap script failed.")
                    : bootstrap_error;

                while (!queue_.empty()) {
                    std::shared_ptr<qt_qthreadruntime_job> job = queue_.front();
                    queue_.pop_front();
                    if (!job) {
                        continue;
                    }
                    jobs_.erase(job->id);
                    results_[job->id] = failed;
                }
                dropEventQueuesLocked(true);
                result_cv_.notify_all();
                qt_qthreadruntime_shutdown_worker_request();
                return;
            }
        }

        while (true) {
            std::shared_ptr<qt_qthreadruntime_job> job;
            {
                std::unique_lock<std::mutex> lock(mutex_);
                job_cv_.wait(lock, [this]() {
                    return stopping_ || !queue_.empty();
                });

                if (stopping_ && queue_.empty()) {
                    break;
                }

                job = queue_.front();
                queue_.pop_front();
            }

            if (!job) {
                continue;
            }

            qt_qthreadruntime_result result = executeJob(job);

            {
                std::lock_guard<std::mutex> lock(mutex_);
                jobs_.erase(job->id);
                auto queue_it = inbound_events_by_job_.find(job->id);
                if (queue_it != inbound_events_by_job_.end()) {
                    size_t dropped = queue_it->second.size();
                    if (dropped > 0) {
                        stats_events_in_dropped_shutdown_ += dropped;
                        qt_qthreadruntime_total_events_in_dropped_shutdown.fetch_add((uint64_t) dropped, std::memory_order_acq_rel);
                    }
                    inbound_events_by_job_.erase(queue_it);
                }
                result.ready = true;
                results_[job->id] = std::move(result);
                stats_drained_++;
                qt_qthreadruntime_total_drained.fetch_add(1, std::memory_order_acq_rel);
            }
            result_cv_.notify_all();
            inbound_cv_.notify_all();
        }

        {
            std::lock_guard<std::mutex> lock(mutex_);
            dropEventQueuesLocked(true);
        }

        qt_qthreadruntime_shutdown_worker_request();
#endif
    }

    static bool serializeValue(zval *value, std::string *out)
    {
        if (value == nullptr || out == nullptr) {
            return false;
        }

        zval serializer;
        zval retval;
        zval param;
        ZVAL_STRINGL(&serializer, "serialize", sizeof("serialize") - 1);
        ZVAL_COPY(&param, value);
        ZVAL_UNDEF(&retval);

        int status = call_user_function(EG(function_table), NULL, &serializer, &retval, 1, &param);
        zval_ptr_dtor(&param);
        zval_ptr_dtor(&serializer);

        if (status != SUCCESS || EG(exception) != NULL || Z_TYPE(retval) != IS_STRING) {
            if (EG(exception) != NULL) {
                zend_clear_exception();
            }
            if (!Z_ISUNDEF(retval)) {
                zval_ptr_dtor(&retval);
            }
            return false;
        }

        out->assign(Z_STRVAL(retval), Z_STRLEN(retval));
        zval_ptr_dtor(&retval);
        return true;
    }

    static bool unserializeValue(const std::string &payload, zval *out)
    {
        if (out == nullptr) {
            return false;
        }

        zval serializer;
        zval arg;
        zval retval;
        ZVAL_STRINGL(&serializer, "unserialize", sizeof("unserialize") - 1);
        ZVAL_STRINGL(&arg, payload.data(), payload.size());
        ZVAL_UNDEF(&retval);

        int status = call_user_function(EG(function_table), NULL, &serializer, &retval, 1, &arg);
        zval_ptr_dtor(&arg);
        zval_ptr_dtor(&serializer);

        if (status != SUCCESS || EG(exception) != NULL) {
            if (EG(exception) != NULL) {
                zend_clear_exception();
            }
            if (!Z_ISUNDEF(retval)) {
                zval_ptr_dtor(&retval);
            }
            return false;
        }

        ZVAL_COPY_VALUE(out, &retval);
        return true;
    }

    static qt_qthreadruntime_result makeErrorResult(std::string class_name, std::string message, zend_long code = 0, bool fatal = false)
    {
        qt_qthreadruntime_result result;
        result.success = false;
        result.canceled = false;
        result.error.class_name = std::move(class_name);
        result.error.message = std::move(message);
        result.error.code = code;
        result.error.is_fatal = fatal;
        return result;
    }

    qt_qthreadruntime_result executeJob(const std::shared_ptr<qt_qthreadruntime_job> &job)
    {
        if (job->canceled.load(std::memory_order_acquire)) {
            qt_qthreadruntime_result result;
            result.success = false;
            result.canceled = true;
            return result;
        }

        qt_qthreadruntime_result result;
        bool bailed_out = false;

        struct qt_qthreadruntime_tls_guard {
            qt_qthreadruntime_state *prev_state;
            uint64_t prev_job_id;
            explicit qt_qthreadruntime_tls_guard(qt_qthreadruntime_state *state, uint64_t job_id)
                : prev_state(qt_qthreadruntime_tls_current_state)
                , prev_job_id(qt_qthreadruntime_tls_current_job_id)
            {
                qt_qthreadruntime_tls_current_state = state;
                qt_qthreadruntime_tls_current_job_id = job_id;
            }
            ~qt_qthreadruntime_tls_guard()
            {
                qt_qthreadruntime_tls_current_state = prev_state;
                qt_qthreadruntime_tls_current_job_id = prev_job_id;
            }
        } tls_guard(this, job->id);

        zend_first_try {
            zval args_zv;
            ZVAL_UNDEF(&args_zv);
            if (!unserializeValue(job->args_payload, &args_zv) || Z_TYPE(args_zv) != IS_ARRAY) {
                if (Z_TYPE(args_zv) != IS_UNDEF) {
                    zval_ptr_dtor(&args_zv);
                }
                return makeErrorResult("RuntimeException", "Failed to unserialize worker arguments.");
            }

            zval callable_zv;
            if (!unserializeValue(job->callable_payload, &callable_zv)) {
                zval_ptr_dtor(&args_zv);
                return makeErrorResult("RuntimeException", "Failed to unserialize worker callable.");
            }

            uint32_t argc = (uint32_t) zend_hash_num_elements(Z_ARRVAL(args_zv));
            std::vector<zval> params;
            params.reserve(argc);
            zval *entry = NULL;
            ZEND_HASH_FOREACH_VAL(Z_ARRVAL(args_zv), entry) {
                zval param;
                ZVAL_COPY(&param, entry);
                params.push_back(param);
            } ZEND_HASH_FOREACH_END();

            zval retval;
            ZVAL_UNDEF(&retval);

            zend_fcall_info fci;
            zend_fcall_info_cache fcc;
            if (zend_fcall_info_init(&callable_zv, 0, &fci, &fcc, NULL, NULL) != SUCCESS) {
                for (zval &param : params) {
                    zval_ptr_dtor(&param);
                }
                zval_ptr_dtor(&callable_zv);
                zval_ptr_dtor(&args_zv);
                return makeErrorResult("RuntimeException", "Worker callable is not invokable.");
            }

            fci.retval = &retval;
            fci.param_count = argc;
            fci.params = argc > 0 ? params.data() : NULL;

            int call_status = zend_call_function(&fci, &fcc);

            for (zval &param : params) {
                zval_ptr_dtor(&param);
            }
            zval_ptr_dtor(&callable_zv);
            zval_ptr_dtor(&args_zv);

            if (call_status != SUCCESS) {
                if (!Z_ISUNDEF(retval)) {
                    zval_ptr_dtor(&retval);
                }
                return makeErrorResult("RuntimeException", "zend_call_function() failed in worker runtime.");
            }

            if (EG(exception) != NULL) {
                zval ex_zv;
                ZVAL_OBJ_COPY(&ex_zv, EG(exception));
                zend_clear_exception();

                zend_object *ex_obj = Z_OBJ(ex_zv);
                zend_long error_code = 0;
                std::string class_name = ex_obj != NULL && ex_obj->ce != NULL
                    ? std::string(ZSTR_VAL(ex_obj->ce->name), ZSTR_LEN(ex_obj->ce->name))
                    : std::string("RuntimeException");
                std::string message = "Worker exception.";
                if (ex_obj != NULL) {
                    zval rv;
                    zval *message_prop = zend_read_property_ex(ex_obj->ce, ex_obj, ZSTR_KNOWN(ZEND_STR_MESSAGE), 1, &rv);
                    if (message_prop != NULL) {
                        zend_string *msg = zval_get_string(message_prop);
                        if (msg != NULL) {
                            message.assign(ZSTR_VAL(msg), ZSTR_LEN(msg));
                            zend_string_release(msg);
                        }
                    }

                    zval *code_prop = zend_read_property_ex(ex_obj->ce, ex_obj, ZSTR_KNOWN(ZEND_STR_CODE), 1, &rv);
                    if (code_prop != NULL) {
                        error_code = zval_get_long(code_prop);
                    }
                }

                zval_ptr_dtor(&ex_zv);
                if (!Z_ISUNDEF(retval)) {
                    zval_ptr_dtor(&retval);
                }
                return makeErrorResult(class_name, message, error_code, false);
            }

            if (!serializeValue(&retval, &result.payload)) {
                zval_ptr_dtor(&retval);
                return makeErrorResult("RuntimeException", "Failed to serialize worker result.");
            }

            zval_ptr_dtor(&retval);
            result.success = true;
            result.canceled = false;
        } zend_catch {
            bailed_out = true;
        } zend_end_try();

        if (bailed_out) {
            std::lock_guard<std::mutex> lock(mutex_);
            stats_worker_crash_++;
            qt_qthreadruntime_total_worker_crash.fetch_add(1, std::memory_order_acq_rel);
            return makeErrorResult("RuntimeException", "Worker bailed out while executing the job.", 0, true);
        }

        return result;
    }

    static bool executeBootstrapScript(const std::string &scriptPath, std::string *error)
    {
        if (scriptPath.empty()) {
            return true;
        }

        zend_file_handle file_handle;
        zend_stream_init_filename(&file_handle, scriptPath.c_str());
        zend_result rc = zend_execute_scripts(ZEND_REQUIRE, NULL, 1, &file_handle);
        if (rc == SUCCESS && EG(exception) == NULL) {
            return true;
        }

        if (error != nullptr) {
            if (EG(exception) != NULL) {
                zval ex_zv;
                ZVAL_OBJ_COPY(&ex_zv, EG(exception));
                zend_clear_exception();

                std::string message = "Worker bootstrap script threw an exception.";
                zval rv;
                zval *message_prop = zend_read_property_ex(Z_OBJCE_P(&ex_zv), Z_OBJ(ex_zv), ZSTR_KNOWN(ZEND_STR_MESSAGE), 1, &rv);
                if (message_prop != NULL) {
                    zend_string *msg = zval_get_string(message_prop);
                    if (msg != NULL) {
                        message.assign(ZSTR_VAL(msg), ZSTR_LEN(msg));
                        zend_string_release(msg);
                    }
                }
                zval_ptr_dtor(&ex_zv);
                *error = message;
            } else {
                *error = "Worker bootstrap script could not be executed.";
            }
        }

        return false;
    }

private:
    void scheduleOwnerEventDrain()
    {
        bool expected = false;
        if (!owner_event_drain_scheduled_.compare_exchange_strong(expected, true, std::memory_order_acq_rel)) {
            return;
        }

        std::weak_ptr<qt_qthreadruntime_state> weak = weak_from_this();
        if (!qt_runtime_enqueue_owner_task([weak]() {
            std::shared_ptr<qt_qthreadruntime_state> state = weak.lock();
            if (!state) {
                return;
            }

            state->owner_event_drain_scheduled_.store(false, std::memory_order_release);
            state->drainEvents(-1);
        })) {
            owner_event_drain_scheduled_.store(false, std::memory_order_release);
        }
    }

    void dropEventQueuesLocked(bool count_as_shutdown)
    {
        size_t outbound_dropped = outbound_events_.size();
        if (count_as_shutdown && outbound_dropped > 0) {
            stats_events_out_dropped_shutdown_ += outbound_dropped;
            qt_qthreadruntime_total_events_out_dropped_shutdown.fetch_add((uint64_t) outbound_dropped, std::memory_order_acq_rel);
        }
        outbound_events_.clear();

        size_t inbound_dropped = 0;
        for (auto &entry : inbound_events_by_job_) {
            inbound_dropped += entry.second.size();
            entry.second.clear();
        }
        if (count_as_shutdown && inbound_dropped > 0) {
            stats_events_in_dropped_shutdown_ += inbound_dropped;
            qt_qthreadruntime_total_events_in_dropped_shutdown.fetch_add((uint64_t) inbound_dropped, std::memory_order_acq_rel);
        }
        inbound_events_by_job_.clear();
    }

    mutable std::mutex mutex_;
    std::condition_variable job_cv_;
    std::condition_variable result_cv_;
    std::condition_variable inbound_cv_;
    std::deque<std::shared_ptr<qt_qthreadruntime_job>> queue_;
    std::deque<qt_qthreadruntime_event_message> outbound_events_;
    std::unordered_map<uint64_t, std::deque<qt_qthreadruntime_event_message>> inbound_events_by_job_;
    std::unordered_map<uint64_t, std::shared_ptr<qt_qthreadruntime_job>> jobs_;
    std::unordered_map<uint64_t, std::shared_ptr<qt_qthreadruntime_listener_t>> listeners_by_id_;
    std::unordered_map<std::string, std::vector<uint64_t>> listener_ids_by_event_;
    std::unordered_map<uint64_t, qt_qthreadruntime_result> results_;
    std::unique_ptr<qt_qthreadruntime_worker_thread> worker_thread_;
    uint64_t next_job_id_{1};
    uint64_t next_listener_id_{1};
    uint64_t stats_enqueued_{0};
    uint64_t stats_drained_{0};
    uint64_t stats_canceled_{0};
    uint64_t stats_rejected_full_{0};
    uint64_t stats_rejected_stopping_{0};
    uint64_t stats_timeouts_{0};
    uint64_t stats_worker_crash_{0};
    uint64_t stats_listeners_registered_{0};
    uint64_t stats_events_out_enqueued_{0};
    uint64_t stats_events_out_drained_{0};
    uint64_t stats_events_out_dropped_full_{0};
    uint64_t stats_events_out_dropped_shutdown_{0};
    uint64_t stats_events_in_enqueued_{0};
    uint64_t stats_events_in_drained_{0};
    uint64_t stats_events_in_dropped_full_{0};
    uint64_t stats_events_in_dropped_shutdown_{0};
    uint64_t stats_listener_dispatch_errors_{0};
    size_t max_queue_depth_{qt_qthreadruntime_env_queue_depth()};
    size_t max_event_out_queue_depth_{qt_qthreadruntime_env_event_out_queue_depth()};
    size_t max_event_in_queue_depth_{qt_qthreadruntime_env_event_in_queue_depth()};
    std::string bootstrap_script_;
    qt_qthreadruntime_request_snapshot owner_request_snapshot_;
    bool running_{false};
    bool stopping_{false};
    bool worker_bootstrap_failed_{false};
    std::atomic_bool owner_event_drain_scheduled_{false};
};

struct qt_qthread_task_host {
    std::atomic_uint32_t refcount_{1};
    std::mutex mutex_;
    std::condition_variable inbound_cv_;
    std::condition_variable future_cv_;
    std::deque<qt_qthreadruntime_event_message> outbound_events_;
    std::deque<qt_qthreadruntime_event_message> inbound_events_;
    std::unordered_map<uint64_t, std::shared_ptr<qt_qthreadruntime_listener_t>> listeners_by_id_;
    std::unordered_map<std::string, std::vector<uint64_t>> listener_ids_by_event_;
    std::unordered_map<uint64_t, qt_qthreadruntime_result> future_results_;
    std::unordered_set<uint64_t> canceled_future_tokens_;
    uint64_t next_listener_id_{1};
    uint64_t next_task_token_{1};
    size_t max_event_out_queue_depth_{qt_qthreadruntime_env_event_out_queue_depth()};
    size_t max_event_in_queue_depth_{qt_qthreadruntime_env_event_in_queue_depth()};
    std::string bootstrap_script_;
    qt_qthreadruntime_request_snapshot owner_request_snapshot_;
    std::string pending_callable_name_;
    std::string pending_args_payload_;
    uint64_t pending_task_token_{0};
    uint64_t active_task_token_{0};
    bool has_pending_task_{false};
    bool task_running_{false};
    bool stopping_{false};
    bool interrupted_{false};
    bool moved_runtime_active_{false};
    std::atomic_bool owner_event_drain_scheduled_{false};
    QPointer<QThread> bound_thread_;
    QMetaObject::Connection started_connection_;
    QMetaObject::Connection finished_connection_;
    std::vector<qt_qthreadruntime_moved_object> pending_moved_objects_;
    std::vector<zval> active_moved_wrappers_;
    std::vector<uint64_t> active_moved_tokens_;

    bool setBootstrapScript(const std::string &path, std::string *error)
    {
        std::lock_guard<std::mutex> lock(mutex_);
        if (task_running_ || has_pending_task_) {
            if (error != nullptr) {
                *error = "Cannot change bootstrap script while task is active.";
            }
            return false;
        }

        bootstrap_script_ = path;
        return true;
    }

    bool registerMovedObject(
        QThread *thread,
        QObject *native_object,
        zend_object *source_object,
        bool native_is_generated_subclass,
        bool native_is_virtual_trampoline,
        bool prevent_destroy,
        void (*rebind_php_object)(void *native_ptr, zend_object *php_object, zend_class_entry *actual_ce),
        uint64_t *token_out,
        std::string *error
    )
    {
        if (thread == nullptr || native_object == nullptr || source_object == nullptr || token_out == nullptr) {
            if (error != nullptr) {
                *error = "Invalid moveToThread registration state.";
            }
            return false;
        }

        if (!qt_runtime_can_call_zend()) {
            if (error != nullptr) {
                *error = "QObject::moveToThread() can only be initiated from the owner request thread.";
            }
            return false;
        }

        if (thread->isRunning()) {
            if (error != nullptr) {
                *error = "QObject::moveToThread() currently requires the target QThread to be stopped before move.";
            }
            return false;
        }

        qt_qthreadruntime_moved_object moved;
        moved.native_object = native_object;
        moved.native_is_generated_subclass = native_is_generated_subclass;
        moved.native_is_virtual_trampoline = native_is_virtual_trampoline;
        moved.prevent_destroy = prevent_destroy;
        moved.rebind_php_object = rebind_php_object;
        moved.class_name.assign(ZSTR_VAL(source_object->ce->name), ZSTR_LEN(source_object->ce->name));

        if (source_object->ce->type == ZEND_USER_CLASS) {
            if (source_object->ce->info.user.filename == NULL || ZSTR_LEN(source_object->ce->info.user.filename) == 0) {
                if (error != nullptr) {
                    *error = "Moved PHP QObject subclasses must be defined in a loadable file.";
                }
                return false;
            }

            moved.class_file.assign(
                ZSTR_VAL(source_object->ce->info.user.filename),
                ZSTR_LEN(source_object->ce->info.user.filename)
            );
        }

        if (!qt_qthreadruntime_capture_object_properties(source_object, &moved.properties, error)) {
            return false;
        }

        std::lock_guard<std::mutex> lock(mutex_);
        if (stopping_ || task_running_ || has_pending_task_ || moved_runtime_active_) {
            if (error != nullptr) {
                *error = "Target QThread cannot accept moved QObject workers right now.";
            }
            return false;
        }

        if (!bound_thread_.isNull() && bound_thread_ != thread) {
            if (error != nullptr) {
                *error = "Target QThread host is already bound to a different native thread.";
            }
            return false;
        }

        bound_thread_ = thread;
        qt_qthreadruntime_capture_request_snapshot(&owner_request_snapshot_);
        moved.token = qt_qthreadruntime_register_moved_object_record(native_object, thread);
        if (moved.token == 0) {
            if (error != nullptr) {
                *error = "Failed to create moved QObject registry entry.";
            }
            return false;
        }
        pending_moved_objects_.push_back(std::move(moved));
        *token_out = pending_moved_objects_.back().token;
        return true;
    }

    void retain()
    {
        refcount_.fetch_add(1, std::memory_order_acq_rel);
    }

    void release()
    {
        uint32_t previous = refcount_.fetch_sub(1, std::memory_order_acq_rel);
        if (previous == 1) {
            delete this;
        }
    }

    bool on(const std::string &event_name, zval *listener, uint64_t *listener_id, std::string *error)
    {
        return onForToken(0, event_name, listener, listener_id, error);
    }

    bool onForToken(uint64_t task_token, const std::string &event_name, zval *listener, uint64_t *listener_id, std::string *error)
    {
        if (listener == nullptr || listener_id == nullptr || error == nullptr) {
            return false;
        }

        if (!qt_runtime_can_call_zend()) {
            *error = "Listeners can only be registered from owner request thread.";
            return false;
        }

        std::shared_ptr<qt_qthreadruntime_listener_t> handle = std::make_shared<qt_qthreadruntime_listener_t>();
        memset(&handle->fci, 0, sizeof(handle->fci));
        memset(&handle->fci_cache, 0, sizeof(handle->fci_cache));
        ZVAL_UNDEF(&handle->fci.function_name);

        char *fci_error = NULL;
        if (zend_fcall_info_init(listener, 0, &handle->fci, &handle->fci_cache, NULL, &fci_error) != SUCCESS) {
            if (fci_error != NULL) {
                *error = std::string("Invalid listener: ") + fci_error;
                efree(fci_error);
            } else {
                *error = "Invalid listener.";
            }
            return false;
        }
        Z_TRY_ADDREF(handle->fci.function_name);

        std::lock_guard<std::mutex> lock(mutex_);
        handle->id = next_listener_id_++;
        handle->event_name = event_name;
        handle->task_token_filter = task_token;
        listeners_by_id_[handle->id] = handle;
        listener_ids_by_event_[event_name].push_back(handle->id);
        *listener_id = handle->id;
        return true;
    }

    bool off(uint64_t listener_id)
    {
        std::shared_ptr<qt_qthreadruntime_listener_t> handle;
        {
            std::lock_guard<std::mutex> lock(mutex_);
            auto it = listeners_by_id_.find(listener_id);
            if (it == listeners_by_id_.end()) {
                return false;
            }

            handle = it->second;
            listeners_by_id_.erase(it);
            auto event_it = listener_ids_by_event_.find(handle->event_name);
            if (event_it != listener_ids_by_event_.end()) {
                std::vector<uint64_t> &ids = event_it->second;
                ids.erase(std::remove(ids.begin(), ids.end(), listener_id), ids.end());
                if (ids.empty()) {
                    listener_ids_by_event_.erase(event_it);
                }
            }
        }

        qt_qthreadruntime_listener_clear(handle);
        return true;
    }

    zend_long drainEvents(zend_long max_items)
    {
        if (!qt_runtime_can_call_zend() || max_items == 0) {
            return 0;
        }

        zend_long processed = 0;
        while (max_items < 0 || processed < max_items) {
            qt_qthreadruntime_event_message message;
            std::vector<std::shared_ptr<qt_qthreadruntime_listener_t>> listeners;
            {
                std::lock_guard<std::mutex> lock(mutex_);
                if (outbound_events_.empty()) {
                    break;
                }

                message = std::move(outbound_events_.front());
                outbound_events_.pop_front();

                auto event_it = listener_ids_by_event_.find(message.event_name);
                if (event_it != listener_ids_by_event_.end()) {
                    listeners.reserve(event_it->second.size());
                    for (uint64_t id : event_it->second) {
                        auto listener_it = listeners_by_id_.find(id);
                        if (listener_it != listeners_by_id_.end() && listener_it->second) {
                            listeners.push_back(listener_it->second);
                        }
                    }
                }
            }

            processed++;
            if (listeners.empty()) {
                continue;
            }

            zval payload;
            if (!qt_qthreadruntime_value_to_zval(message.payload, &payload)) {
                continue;
            }

            zval envelope;
            array_init(&envelope);
            add_assoc_stringl(&envelope, "event", message.event_name.data(), message.event_name.size());
            add_assoc_long(&envelope, "jobId", (zend_long) message.job_id);
            add_assoc_zval(&envelope, "payload", &payload);

            for (const std::shared_ptr<qt_qthreadruntime_listener_t> &listener : listeners) {
                if (!qt_qthreadruntime_listener_invoke(listener, &envelope) || EG(exception) != NULL) {
                    if (EG(exception) != NULL) {
                        zend_clear_exception();
                    }
                    qt_qthreadruntime_total_listener_dispatch_errors.fetch_add(1, std::memory_order_acq_rel);
                }
            }

            zval_ptr_dtor(&envelope);
        }

        std::lock_guard<std::mutex> lock(mutex_);
        if (!outbound_events_.empty()) {
            scheduleOwnerEventDrain();
        }

        return processed;
    }

    bool send(const std::string &event_name, zval *payload, std::string *error)
    {
        qt_qthreadruntime_value payload_value;
        if (payload == nullptr) {
            if (error != nullptr) {
                *error = "Payload must not be null.";
            }
            return false;
        }

        if (!qt_qthreadruntime_zval_to_value(payload, &payload_value, error)) {
            return false;
        }

        std::lock_guard<std::mutex> lock(mutex_);
        if (stopping_ || (!task_running_ && !has_pending_task_)) {
            return false;
        }

        if (inbound_events_.size() >= max_event_in_queue_depth_) {
            return false;
        }

        qt_qthreadruntime_event_message message;
        message.job_id = 0;
        message.event_name = event_name;
        message.payload = std::move(payload_value);
        inbound_events_.push_back(std::move(message));
        inbound_cv_.notify_all();
        return true;
    }

    bool start(QThread *thread, const std::string &callable_name, const std::string &args_payload, bool has_priority, int priority, std::string *error)
    {
        return startInternal(thread, callable_name, args_payload, has_priority, priority, 0, false, nullptr, error);
    }

    bool startFuture(QThread *thread, const std::string &callable_name, const std::string &args_payload, bool has_priority, int priority, uint64_t *task_token, std::string *error)
    {
        return startInternal(thread, callable_name, args_payload, has_priority, priority, 0, true, task_token, error);
    }

    bool startInternal(
        QThread *thread,
        const std::string &callable_name,
        const std::string &args_payload,
        bool has_priority,
        int priority,
        uint64_t forced_token,
        bool allocate_token,
        uint64_t *out_token,
        std::string *error
    )
    {
        if (thread == nullptr) {
            if (error != nullptr) {
                *error = "QThread native instance is not initialized.";
            }
            return false;
        }

        {
            std::lock_guard<std::mutex> lock(mutex_);
            if (stopping_) {
                if (error != nullptr) {
                    *error = "QThread task runtime is stopping.";
                }
                return false;
            }
            if (task_running_ || has_pending_task_) {
                if (error != nullptr) {
                    *error = "QThread task is already active.";
                }
                return false;
            }
            if (thread->isRunning()) {
                if (error != nullptr) {
                    *error = "QThread is already running.";
                }
                return false;
            }

            pending_callable_name_ = callable_name;
            pending_args_payload_ = args_payload;
            qt_qthreadruntime_capture_request_snapshot(&owner_request_snapshot_);
            has_pending_task_ = true;
            interrupted_ = false;
            pending_task_token_ = forced_token;
            if (allocate_token) {
                pending_task_token_ = next_task_token_++;
                qt_qthreadruntime_result pending_result;
                pending_result.ready = false;
                future_results_[pending_task_token_] = std::move(pending_result);
            }
            if (out_token != nullptr) {
                *out_token = pending_task_token_;
            }
            bound_thread_ = thread;
            inbound_events_.clear();
        }

        QObject::disconnect(started_connection_);
        QObject::disconnect(finished_connection_);

        finished_connection_ = QObject::connect(
            thread,
            &QThread::finished,
            thread,
            [this]() {
                std::lock_guard<std::mutex> lock(mutex_);
                has_pending_task_ = false;
                task_running_ = false;
                active_task_token_ = 0;
                inbound_events_.clear();
                inbound_cv_.notify_all();
            },
            Qt::DirectConnection
        );

        if (has_priority) {
            thread->start((QThread::Priority) priority);
        } else {
            thread->start();
        }

        return true;
    }

    bool onOwnerInterruptionRequest()
    {
        std::lock_guard<std::mutex> lock(mutex_);
        if (!task_running_ && !has_pending_task_) {
            return false;
        }

        interrupted_ = true;
        uint64_t token = active_task_token_ != 0 ? active_task_token_ : pending_task_token_;
        if (token != 0) {
            canceled_future_tokens_.insert(token);
        }
        if (inbound_events_.size() < max_event_in_queue_depth_) {
            qt_qthreadruntime_event_message message;
            message.job_id = token;
            message.event_name = "__interrupt";
            message.payload.type = qt_qthreadruntime_value_type::array_value;
            inbound_events_.push_back(std::move(message));
            inbound_cv_.notify_all();
        }
        return true;
    }

    bool isTaskRunning()
    {
        std::lock_guard<std::mutex> lock(mutex_);
        return task_running_ || has_pending_task_;
    }

    bool hasFuture(uint64_t task_token)
    {
        std::lock_guard<std::mutex> lock(mutex_);
        return future_results_.find(task_token) != future_results_.end();
    }

    bool isFutureRunning(uint64_t task_token)
    {
        std::lock_guard<std::mutex> lock(mutex_);
        auto it = future_results_.find(task_token);
        if (it == future_results_.end()) {
            return false;
        }

        return !it->second.ready;
    }

    bool isFutureFinished(uint64_t task_token)
    {
        std::lock_guard<std::mutex> lock(mutex_);
        auto it = future_results_.find(task_token);
        return it != future_results_.end() && it->second.ready;
    }

    bool isFutureCanceled(uint64_t task_token)
    {
        std::lock_guard<std::mutex> lock(mutex_);
        auto it = future_results_.find(task_token);
        return it != future_results_.end() && it->second.ready && it->second.canceled;
    }

    bool cancelFuture(uint64_t task_token)
    {
        std::lock_guard<std::mutex> lock(mutex_);
        auto it = future_results_.find(task_token);
        if (it == future_results_.end()) {
            return false;
        }
        if (it->second.ready) {
            return false;
        }

        canceled_future_tokens_.insert(task_token);
        if (has_pending_task_ && pending_task_token_ == task_token) {
            has_pending_task_ = false;
            pending_task_token_ = 0;
            pending_callable_name_.clear();
            pending_args_payload_.clear();
            it->second.ready = true;
            it->second.success = false;
            it->second.canceled = true;
            future_cv_.notify_all();
            inbound_cv_.notify_all();
            return true;
        }

        if (task_running_ && active_task_token_ == task_token) {
            interrupted_ = true;
            if (inbound_events_.size() < max_event_in_queue_depth_) {
                qt_qthreadruntime_event_message message;
                message.job_id = task_token;
                message.event_name = "__interrupt";
                message.payload.type = qt_qthreadruntime_value_type::array_value;
                inbound_events_.push_back(std::move(message));
            }
            inbound_cv_.notify_all();
            return true;
        }

        return false;
    }

    bool waitFuture(uint64_t task_token, zend_long timeout_ms, bool *finished)
    {
        if (finished == nullptr) {
            return false;
        }

        std::unique_lock<std::mutex> lock(mutex_);
        auto it = future_results_.find(task_token);
        if (it == future_results_.end()) {
            return false;
        }

        auto ready = [&]() -> bool {
            auto current = future_results_.find(task_token);
            return current == future_results_.end() || current->second.ready;
        };

        if (timeout_ms <= 0) {
            future_cv_.wait(lock, ready);
        } else if (!future_cv_.wait_for(lock, std::chrono::milliseconds(timeout_ms), ready)) {
            *finished = false;
            return true;
        }

        auto current = future_results_.find(task_token);
        if (current == future_results_.end()) {
            return false;
        }

        *finished = current->second.ready;
        return true;
    }

    bool fetchFutureResult(uint64_t task_token, zend_long timeout_ms, qt_qthreadruntime_result *result, bool *timed_out)
    {
        if (result == nullptr || timed_out == nullptr) {
            return false;
        }

        *timed_out = false;
        bool finished = false;
        if (!waitFuture(task_token, timeout_ms, &finished)) {
            return false;
        }
        if (!finished) {
            *timed_out = true;
            return true;
        }

        std::lock_guard<std::mutex> lock(mutex_);
        auto it = future_results_.find(task_token);
        if (it == future_results_.end()) {
            return false;
        }

        *result = it->second;
        return true;
    }

    bool executePendingOnCurrentThread(QThread *thread)
    {
        if (thread == nullptr) {
            return false;
        }

        bool should_run_task = false;
        {
            std::lock_guard<std::mutex> lock(mutex_);
            should_run_task = has_pending_task_ && !stopping_;
        }

        if (!should_run_task) {
            return false;
        }

        runPendingTaskOnCurrentThread(thread);
        return true;
    }

    bool enterMovedRuntimeOnCurrentThread(QThread *thread)
    {
        if (thread == nullptr) {
            return false;
        }

        std::string bootstrap_script;
        std::vector<qt_qthreadruntime_moved_object> moved_objects;
        {
            std::lock_guard<std::mutex> lock(mutex_);
            if (pending_moved_objects_.empty() || stopping_ || has_pending_task_ || task_running_ || moved_runtime_active_) {
                qt_qthreadruntime_debug_log(
                    "enterMovedRuntime: skipped pending=%zu stopping=%d has_task=%d task_running=%d active=%d",
                    pending_moved_objects_.size(),
                    stopping_ ? 1 : 0,
                    has_pending_task_ ? 1 : 0,
                    task_running_ ? 1 : 0,
                    moved_runtime_active_ ? 1 : 0
                );
                return false;
            }

            bootstrap_script = bootstrap_script_;
            moved_objects = pending_moved_objects_;
            pending_moved_objects_.clear();
            moved_runtime_active_ = true;
            bound_thread_ = thread;
        }
        qt_qthreadruntime_debug_log(
            "enterMovedRuntime: activating objects=%zu bootstrap=%zu",
            moved_objects.size(),
            bootstrap_script.size()
        );

#if !defined(ZTS)
        (void) bootstrap_script;
        (void) moved_objects;
        return false;
#else
        qt_qthreadruntime_tls_worker_request = true;
        qt_qthreadruntime_tls_bound_thread = thread;
        qt_qthreadruntime_tls_interrupted = false;

        bool startup_ok = qt_qthreadruntime_prepare_worker_request(owner_request_snapshot_);
        qt_qthreadruntime_debug_log("enterMovedRuntime: startup_ok=%d", startup_ok ? 1 : 0);
        if (!startup_ok) {
            php_error_docref(NULL, E_WARNING, "Failed to start PHP worker request for moved QObject runtime.");
        }
        bool bootstrap_ok = true;
        if (startup_ok && !bootstrap_script.empty()) {
            std::string bootstrap_error;
            bootstrap_ok = qt_qthreadruntime_state::executeBootstrapScript(bootstrap_script, &bootstrap_error);
            if (!bootstrap_ok) {
                php_error_docref(NULL, E_WARNING, "QThread moved QObject bootstrap failed: %s", bootstrap_error.c_str());
            }
        }
        qt_qthreadruntime_debug_log("enterMovedRuntime: bootstrap_ok=%d", bootstrap_ok ? 1 : 0);

        std::vector<zval> wrappers;
        std::vector<uint64_t> active_tokens;
        std::string materialize_error;
        bool materialized = startup_ok && bootstrap_ok;
        if (materialized) {
            for (const qt_qthreadruntime_moved_object &moved : moved_objects) {
                std::string class_error;
                zend_class_entry *actual_ce = NULL;
                if (!qt_qthreadruntime_require_class_definition(moved.class_name, moved.class_file, &actual_ce, &class_error)) {
                    php_error_docref(NULL, E_WARNING, "Failed to load moved QObject class %s: %s", moved.class_name.c_str(), class_error.c_str());
                    materialize_error = class_error;
                    materialized = false;
                    break;
                }
                qt_qthreadruntime_debug_log(
                    "enterMovedRuntime: loaded class=%s file=%s",
                    moved.class_name.c_str(),
                    moved.class_file.c_str()
                );

                zval wrapper;
                object_init_ex(&wrapper, actual_ce);
                if (UNEXPECTED(Z_TYPE(wrapper) != IS_OBJECT)) {
                    if (!EG(exception)) {
                        zend_throw_error(NULL, "Failed to instantiate moved QObject wrapper for %s.", moved.class_name.c_str());
                    }
                    materialize_error = "Destination wrapper instantiation failed.";
                    materialized = false;
                    break;
                }
                qt_qthreadruntime_debug_log("enterMovedRuntime: wrapper instantiated class=%s", moved.class_name.c_str());

                qt_qobject_object *intern = qt_qobject_from_obj(Z_OBJ(wrapper));
                intern->native_ptr = moved.native_object;
                intern->native_is_generated_subclass = moved.native_is_generated_subclass;
                intern->native_is_virtual_trampoline = moved.native_is_virtual_trampoline;
                intern->prevent_destroy = moved.prevent_destroy;
                intern->native_rebind_php_object = moved.rebind_php_object;
                qt_php_signal_register_live_wrapper(static_cast<QObject *>(intern->native_ptr), &intern->std);

                if (!qt_qthreadruntime_restore_object_properties(&intern->std, moved.properties, &class_error)) {
                    zval_ptr_dtor(&wrapper);
                    php_error_docref(NULL, E_WARNING, "Failed to restore moved QObject state for %s: %s", moved.class_name.c_str(), class_error.c_str());
                    materialize_error = class_error;
                    materialized = false;
                    break;
                }
                qt_qthreadruntime_debug_log(
                    "enterMovedRuntime: restored properties class=%s count=%zu",
                    moved.class_name.c_str(),
                    moved.properties.size()
                );

                if (intern->native_is_virtual_trampoline && intern->native_rebind_php_object != NULL) {
                    intern->native_rebind_php_object(intern->native_ptr, &intern->std, actual_ce);
                    qt_qthreadruntime_debug_log("enterMovedRuntime: rebound trampoline class=%s", moved.class_name.c_str());
                }

                qt_qthreadruntime_set_moved_object_active_wrapper(moved.token, Z_OBJ(wrapper));
                wrappers.push_back(wrapper);
                active_tokens.push_back(moved.token);
            }
        }

        if (!materialized) {
            qt_qthreadruntime_debug_log("enterMovedRuntime: materialized=0");
            if (materialize_error.empty() && startup_ok && bootstrap_ok) {
                materialize_error = "Moved QObject runtime materialization failed.";
            }
            if (!materialize_error.empty()) {
                php_error_docref(NULL, E_WARNING, "Moved QObject activation failed: %s", materialize_error.c_str());
            }
            for (uint64_t token : active_tokens) {
                qt_qthreadruntime_set_moved_object_active_wrapper(token, NULL);
            }
            for (zval &wrapper : wrappers) {
                zval_ptr_dtor(&wrapper);
            }
            if (startup_ok) {
                qt_qthreadruntime_shutdown_worker_request();
            }
            std::lock_guard<std::mutex> lock(mutex_);
            moved_runtime_active_ = false;
            bound_thread_.clear();
            return true;
        }

        size_t active_wrapper_count = wrappers.size();
        {
            std::lock_guard<std::mutex> lock(mutex_);
            active_moved_wrappers_ = std::move(wrappers);
            active_moved_tokens_ = std::move(active_tokens);
        }
        qt_qthreadruntime_debug_log("enterMovedRuntime: materialized=1 wrappers=%zu", active_wrapper_count);

        return true;
#endif
    }

    bool isMovedRuntimeActive()
    {
        std::lock_guard<std::mutex> lock(mutex_);
        return moved_runtime_active_;
    }

    void leaveMovedRuntimeOnCurrentThread()
    {
        std::vector<zval> wrappers;
        std::vector<uint64_t> tokens;
        {
            std::lock_guard<std::mutex> lock(mutex_);
            wrappers.swap(active_moved_wrappers_);
            tokens.swap(active_moved_tokens_);
            moved_runtime_active_ = false;
            bound_thread_.clear();
        }

        for (uint64_t token : tokens) {
            qt_qthreadruntime_set_moved_object_active_wrapper(token, NULL);
        }
        for (zval &wrapper : wrappers) {
            zval_ptr_dtor(&wrapper);
        }

#if defined(ZTS)
        qt_qthreadruntime_shutdown_worker_request();
#endif
    }

    bool publishFromWorker(const std::string &event_name, const qt_qthreadruntime_value &payload)
    {
        std::lock_guard<std::mutex> lock(mutex_);
        if (stopping_) {
            return false;
        }
        if (outbound_events_.size() >= max_event_out_queue_depth_) {
            return false;
        }

        qt_qthreadruntime_event_message message;
        message.job_id = active_task_token_;
        message.event_name = event_name;
        message.payload = payload;
        outbound_events_.push_back(std::move(message));
        scheduleOwnerEventDrain();
        return true;
    }

    bool receiveForWorker(zend_long timeout_ms, qt_qthreadruntime_event_message *message)
    {
        if (message == nullptr) {
            return false;
        }

        std::unique_lock<std::mutex> lock(mutex_);
        auto ready = [this]() -> bool {
            return stopping_ || !inbound_events_.empty();
        };

        if (timeout_ms <= 0) {
            inbound_cv_.wait(lock, ready);
        } else if (!inbound_cv_.wait_for(lock, std::chrono::milliseconds(timeout_ms), ready)) {
            return false;
        }

        if (stopping_ || inbound_events_.empty()) {
            return false;
        }

        *message = std::move(inbound_events_.front());
        inbound_events_.pop_front();
        if (message->event_name == "__interrupt") {
            qt_qthreadruntime_tls_interrupted = true;
        }
        return true;
    }

    bool workerIsCanceled()
    {
        std::lock_guard<std::mutex> lock(mutex_);
        return interrupted_;
    }

    void shutdown(zend_long timeout_ms)
    {
        QPointer<QThread> thread;
        std::vector<zval> moved_wrappers;
        std::vector<uint64_t> moved_tokens;
        {
            std::lock_guard<std::mutex> lock(mutex_);
            stopping_ = true;
            has_pending_task_ = false;
            task_running_ = false;
            moved_runtime_active_ = false;
            pending_task_token_ = 0;
            active_task_token_ = 0;
            inbound_events_.clear();
            outbound_events_.clear();
            pending_moved_objects_.clear();
            moved_wrappers.swap(active_moved_wrappers_);
            moved_tokens.swap(active_moved_tokens_);
            for (auto &entry : future_results_) {
                if (!entry.second.ready) {
                    entry.second.ready = true;
                    entry.second.success = false;
                    entry.second.canceled = true;
                }
            }
            inbound_cv_.notify_all();
            future_cv_.notify_all();
            thread = bound_thread_;
            bound_thread_.clear();
        }

        for (uint64_t token : moved_tokens) {
            qt_qthreadruntime_set_moved_object_active_wrapper(token, NULL);
        }

        QObject::disconnect(started_connection_);
        QObject::disconnect(finished_connection_);

        if (!thread.isNull() && thread->isRunning()) {
            thread->requestInterruption();
            thread->quit();
            unsigned long wait_ms = timeout_ms > 0 ? (unsigned long) timeout_ms : 2000UL;
            (void) thread->wait(wait_ms);
        }

        std::vector<std::shared_ptr<qt_qthreadruntime_listener_t>> listeners;
        {
            std::lock_guard<std::mutex> lock(mutex_);
            listeners.reserve(listeners_by_id_.size());
            for (const auto &entry : listeners_by_id_) {
                listeners.push_back(entry.second);
            }
            listeners_by_id_.clear();
            listener_ids_by_event_.clear();
            stopping_ = false;
            interrupted_ = false;
            canceled_future_tokens_.clear();
        }

        for (const auto &listener : listeners) {
            qt_qthreadruntime_listener_clear(listener);
        }

        for (zval &wrapper : moved_wrappers) {
            zval_ptr_dtor(&wrapper);
        }
    }

private:
    void runPendingTaskOnCurrentThread(QThread *thread)
    {
#if !defined(ZTS)
        (void) thread;
        return;
#else
        std::string callable_name;
        std::string args_payload;
        std::string bootstrap_script;
        uint64_t task_token = 0;
        {
            std::lock_guard<std::mutex> lock(mutex_);
            if (!has_pending_task_ || stopping_) {
                return;
            }
            callable_name = pending_callable_name_;
            args_payload = pending_args_payload_;
            bootstrap_script = bootstrap_script_;
            task_token = pending_task_token_;
            has_pending_task_ = false;
            pending_task_token_ = 0;
            active_task_token_ = task_token;
            task_running_ = true;
            interrupted_ = false;
        }

        qt_qthreadruntime_tls_worker_request = true;
        qt_qthreadruntime_tls_current_task_host = this;
        qt_qthreadruntime_tls_current_task_token = task_token;
        qt_qthreadruntime_tls_bound_thread = thread;
        qt_qthreadruntime_tls_interrupted = false;

        bool startup_ok = qt_qthreadruntime_prepare_worker_request(owner_request_snapshot_);
        bool bootstrap_ok = true;
        qt_qthreadruntime_result task_result;
        task_result.success = true;
        task_result.canceled = false;
        if (startup_ok && !bootstrap_script.empty()) {
            std::string bootstrap_error;
            bootstrap_ok = qt_qthreadruntime_state::executeBootstrapScript(bootstrap_script, &bootstrap_error);
            if (!bootstrap_ok) {
                php_error_docref(NULL, E_WARNING, "QThread task bootstrap failed: %s", bootstrap_error.c_str());
                task_result = qt_qthreadruntime_state::makeErrorResult(
                    "RuntimeException",
                    bootstrap_error.empty() ? std::string("QThread task bootstrap failed.") : bootstrap_error
                );
            }
        } else if (!startup_ok) {
            task_result = qt_qthreadruntime_state::makeErrorResult(
                "RuntimeException",
                "Failed to start isolated PHP request for QThread task."
            );
        }

        if (startup_ok && bootstrap_ok) {
            bool bailed_out = false;
            zend_first_try {
                zval args_zv;
                ZVAL_UNDEF(&args_zv);
                if (qt_qthreadruntime_state::unserializeValue(args_payload, &args_zv) && Z_TYPE(args_zv) == IS_ARRAY) {
                    zval callable_zv;
                    ZVAL_STRINGL(&callable_zv, callable_name.data(), callable_name.size());

                    uint32_t argc = (uint32_t) zend_hash_num_elements(Z_ARRVAL(args_zv));
                    std::vector<zval> params;
                    params.reserve(argc);
                    zval *entry = NULL;
                    ZEND_HASH_FOREACH_VAL(Z_ARRVAL(args_zv), entry) {
                        zval param;
                        ZVAL_COPY(&param, entry);
                        params.push_back(param);
                    } ZEND_HASH_FOREACH_END();

                    zval retval;
                    ZVAL_UNDEF(&retval);
                    zend_fcall_info fci;
                    zend_fcall_info_cache fcc;
                    if (zend_fcall_info_init(&callable_zv, 0, &fci, &fcc, NULL, NULL) == SUCCESS) {
                        fci.retval = &retval;
                        fci.param_count = argc;
                        fci.params = argc > 0 ? params.data() : NULL;
                        int call_status = zend_call_function(&fci, &fcc);
                        if (call_status != SUCCESS) {
                            task_result = qt_qthreadruntime_state::makeErrorResult(
                                "RuntimeException",
                                "zend_call_function() failed in QThread task runtime."
                            );
                        } else if (EG(exception) != NULL) {
                            zval ex_zv;
                            ZVAL_OBJ_COPY(&ex_zv, EG(exception));
                            zend_clear_exception();

                            zend_object *ex_obj = Z_OBJ(ex_zv);
                            zend_long error_code = 0;
                            std::string class_name = ex_obj != NULL && ex_obj->ce != NULL
                                ? std::string(ZSTR_VAL(ex_obj->ce->name), ZSTR_LEN(ex_obj->ce->name))
                                : std::string("RuntimeException");
                            std::string message = "Worker exception.";
                            if (ex_obj != NULL) {
                                zval rv;
                                zval *message_prop = zend_read_property_ex(ex_obj->ce, ex_obj, ZSTR_KNOWN(ZEND_STR_MESSAGE), 1, &rv);
                                if (message_prop != NULL) {
                                    zend_string *msg = zval_get_string(message_prop);
                                    if (msg != NULL) {
                                        message.assign(ZSTR_VAL(msg), ZSTR_LEN(msg));
                                        zend_string_release(msg);
                                    }
                                }

                                zval *code_prop = zend_read_property_ex(ex_obj->ce, ex_obj, ZSTR_KNOWN(ZEND_STR_CODE), 1, &rv);
                                if (code_prop != NULL) {
                                    error_code = zval_get_long(code_prop);
                                }
                            }
                            zval_ptr_dtor(&ex_zv);
                            task_result = qt_qthreadruntime_state::makeErrorResult(class_name, message, error_code, false);
                        } else if (!qt_qthreadruntime_state::serializeValue(&retval, &task_result.payload)) {
                            task_result = qt_qthreadruntime_state::makeErrorResult(
                                "RuntimeException",
                                "Failed to serialize QThread task result."
                            );
                        }

                        if (!Z_ISUNDEF(retval)) {
                            zval_ptr_dtor(&retval);
                        }
                    } else {
                        task_result = qt_qthreadruntime_state::makeErrorResult(
                            "RuntimeException",
                            "Worker callable is not invokable in QThread task runtime."
                        );
                    }

                    for (zval &param : params) {
                        zval_ptr_dtor(&param);
                    }
                    zval_ptr_dtor(&callable_zv);
                    zval_ptr_dtor(&args_zv);
                } else {
                    if (Z_TYPE(args_zv) != IS_UNDEF) {
                        zval_ptr_dtor(&args_zv);
                    }
                    task_result = qt_qthreadruntime_state::makeErrorResult(
                        "RuntimeException",
                        "QThread task arguments could not be decoded."
                    );
                }
            } zend_catch {
                bailed_out = true;
            } zend_end_try();

            if (bailed_out) {
                task_result = qt_qthreadruntime_state::makeErrorResult(
                    "RuntimeException",
                    "QThread worker bailed out while executing task.",
                    0,
                    true
                );
            }
        }

        if (startup_ok) {
            qt_qthreadruntime_shutdown_worker_request();
        }

        qt_qthreadruntime_value terminal_payload;
        terminal_payload.type = qt_qthreadruntime_value_type::array_value;
        terminal_payload.array_key_is_string = {true, true};
        terminal_payload.array_string_keys = {"status", "token"};
        terminal_payload.array_index_keys = {0, 0};
        qt_qthreadruntime_value status_value;
        status_value.type = qt_qthreadruntime_value_type::string_value;
        status_value.string_data = task_result.success ? "success" : (task_result.canceled ? "canceled" : "failed");
        qt_qthreadruntime_value token_value;
        token_value.type = qt_qthreadruntime_value_type::long_value;
        token_value.long_data = (zend_long) task_token;
        terminal_payload.array_values.push_back(std::move(status_value));
        terminal_payload.array_values.push_back(std::move(token_value));

        {
            std::lock_guard<std::mutex> lock(mutex_);
            bool cancel_requested = task_token != 0 && canceled_future_tokens_.find(task_token) != canceled_future_tokens_.end();
            if (cancel_requested && !task_result.error.is_fatal) {
                task_result.success = false;
                task_result.canceled = true;
                task_result.payload.clear();
                task_result.error = qt_qthreadruntime_error();
            }

            if (task_token != 0) {
                task_result.ready = true;
                future_results_[task_token] = task_result;
                future_cv_.notify_all();

                qt_qthreadruntime_event_message message;
                message.job_id = task_token;
                message.event_name = "__future_terminal";
                message.payload = std::move(terminal_payload);
                if (outbound_events_.size() < max_event_out_queue_depth_) {
                    outbound_events_.push_back(std::move(message));
                }
            }

            task_running_ = false;
            active_task_token_ = 0;
            inbound_events_.clear();
            inbound_cv_.notify_all();
        }
        scheduleOwnerEventDrain();
#endif
    }

    void scheduleOwnerEventDrain()
    {
        bool expected = false;
        if (!owner_event_drain_scheduled_.compare_exchange_strong(expected, true, std::memory_order_acq_rel)) {
            return;
        }

        retain();
        if (!qt_runtime_enqueue_owner_task([this]() {
            owner_event_drain_scheduled_.store(false, std::memory_order_release);
            this->drainEvents(-1);
            this->release();
        })) {
            owner_event_drain_scheduled_.store(false, std::memory_order_release);
            release();
        }
    }
};

void qt_qthreadruntime_worker_thread::run()
{
    std::shared_ptr<qt_qthreadruntime_state> state = state_.lock();
    if (!state) {
        return;
    }

    state->workerMain();
}

static std::mutex qt_qthreadruntime_registry_mutex;
static std::vector<std::weak_ptr<qt_qthreadruntime_state>> qt_qthreadruntime_registry;

void qt_qthreadruntime_register(const std::shared_ptr<qt_qthreadruntime_state> &state)
{
    std::lock_guard<std::mutex> lock(qt_qthreadruntime_registry_mutex);
    qt_qthreadruntime_registry.erase(
        std::remove_if(
            qt_qthreadruntime_registry.begin(),
            qt_qthreadruntime_registry.end(),
            [](const std::weak_ptr<qt_qthreadruntime_state> &entry) {
                return entry.expired();
            }
        ),
        qt_qthreadruntime_registry.end()
    );
    qt_qthreadruntime_registry.emplace_back(state);
}

void qt_qthreadruntime_unregister(const std::shared_ptr<qt_qthreadruntime_state> &state)
{
    std::lock_guard<std::mutex> lock(qt_qthreadruntime_registry_mutex);
    qt_qthreadruntime_registry.erase(
        std::remove_if(
            qt_qthreadruntime_registry.begin(),
            qt_qthreadruntime_registry.end(),
            [&state](const std::weak_ptr<qt_qthreadruntime_state> &entry) {
                std::shared_ptr<qt_qthreadruntime_state> resolved = entry.lock();
                return !resolved || resolved.get() == state.get();
            }
        ),
        qt_qthreadruntime_registry.end()
    );
}

PHP_QT_API void qt_qthreadruntime_shutdown_all(zend_long timeout_ms)
{
    if (qt_qthreadruntime_tls_worker_request) {
        return;
    }

    std::vector<std::shared_ptr<qt_qthreadruntime_state>> runtimes;
    {
        std::lock_guard<std::mutex> lock(qt_qthreadruntime_registry_mutex);
        runtimes.reserve(qt_qthreadruntime_registry.size());
        for (const std::weak_ptr<qt_qthreadruntime_state> &entry : qt_qthreadruntime_registry) {
            std::shared_ptr<qt_qthreadruntime_state> runtime = entry.lock();
            if (runtime) {
                runtimes.push_back(runtime);
            }
        }
    }

    for (const std::shared_ptr<qt_qthreadruntime_state> &runtime : runtimes) {
        runtime->stop(timeout_ms);
    }
}

