static inline qt_qthreadruntime_state *qt_qthreadruntime_fetch_state(zval *zv)
{
    qt_qthreadruntime_object *intern = Z_QTHREADRUNTIME_P(zv);
    if (intern->state == NULL || intern->state->get() == NULL) {
        return NULL;
    }

    return intern->state->get();
}

static bool qt_qthreadruntime_payload_supported(zval *value)
{
    switch (Z_TYPE_P(value)) {
        case IS_RESOURCE:
            return false;
        case IS_OBJECT:
            return !instanceof_function(Z_OBJCE_P(value), zend_ce_closure);
        case IS_ARRAY: {
            zval *entry = NULL;
            ZEND_HASH_FOREACH_VAL(Z_ARRVAL_P(value), entry) {
                if (entry == NULL || !qt_qthreadruntime_payload_supported(entry)) {
                    return false;
                }
            } ZEND_HASH_FOREACH_END();
            return true;
        }
        default:
            return true;
    }
}

static bool qt_qthreadruntime_event_name_valid(zend_string *event_name)
{
    return event_name != NULL && ZSTR_LEN(event_name) > 0;
}

static bool qt_qthreadruntime_validate_callable(zval *callable, std::string *error)
{
    if (callable == NULL) {
        if (error != NULL) {
            *error = "must be a callable";
        }
        return false;
    }

    if (Z_TYPE_P(callable) == IS_STRING) {
        if (Z_STRLEN_P(callable) > 0) {
            return true;
        }
        if (error != NULL) {
            *error = "must be a non-empty callable string";
        }
        return false;
    }

    if (Z_TYPE_P(callable) != IS_ARRAY || zend_hash_num_elements(Z_ARRVAL_P(callable)) != 2) {
        if (error != NULL) {
            *error = "must be a non-empty callable string or [class-string, method-string] pair; closures/object callables are not supported yet";
        }
        return false;
    }

    zval *first = zend_hash_index_find(Z_ARRVAL_P(callable), 0);
    zval *second = zend_hash_index_find(Z_ARRVAL_P(callable), 1);
    if (first == NULL
        || second == NULL
        || Z_TYPE_P(first) != IS_STRING
        || Z_TYPE_P(second) != IS_STRING
        || Z_STRLEN_P(first) == 0
        || Z_STRLEN_P(second) == 0
    ) {
        if (error != NULL) {
            *error = "must be [class-string, non-empty method-string] when callable is an array";
        }
        return false;
    }

    zend_class_entry *ce = zend_lookup_class_ex(Z_STR_P(first), NULL, ZEND_FETCH_CLASS_NO_AUTOLOAD);
    if (ce != NULL) {
        zend_string *lc_method = zend_string_tolower(Z_STR_P(second));
        zend_function *fn = (zend_function *) zend_hash_find_ptr(&ce->function_table, lc_method);
        zend_string_release(lc_method);
        if (fn != NULL && (fn->common.fn_flags & ZEND_ACC_STATIC) == 0) {
            if (error != NULL) {
                *error = "array callable must reference a static method";
            }
            return false;
        }
    }

    return true;
}

PHP_QT_API bool qt_qthreadruntime_payload_supported_for_worker(zval *value)
{
    if (value == NULL) {
        return false;
    }

    std::string error;
    qt_qthreadruntime_value converted;
    return qt_qthreadruntime_zval_to_value(value, &converted, &error);
}

PHP_QT_API bool qt_qthreadruntime_validate_callable_string(zend_string *callable, std::string *error)
{
    if (callable == NULL || ZSTR_LEN(callable) == 0) {
        if (error != NULL) {
            *error = "must be a non-empty callable string";
        }
        return false;
    }

    return true;
}

PHP_QT_API bool qt_qthreadruntime_serialize_worker_args(zval *args, std::string *out_payload, std::string *error)
{
    if (args == NULL || out_payload == NULL) {
        if (error != NULL) {
            *error = "invalid worker arguments";
        }
        return false;
    }

    if (Z_TYPE_P(args) != IS_ARRAY) {
        if (error != NULL) {
            *error = "worker arguments must be an array";
        }
        return false;
    }

    if (!qt_qthreadruntime_payload_supported_for_worker(args)) {
        if (error != NULL) {
            *error = "worker arguments support only null/bool/int/float/string/array values";
        }
        return false;
    }

    zval copy;
    ZVAL_COPY(&copy, args);
    bool ok = qt_qthreadruntime_state::serializeValue(&copy, out_payload);
    zval_ptr_dtor(&copy);
    if (!ok && error != NULL) {
        *error = "failed to serialize worker arguments";
    }
    return ok;
}

PHP_QT_API bool qt_qthreadruntime_set_thread_interrupted(bool interrupted)
{
    qt_qthreadruntime_tls_interrupted = interrupted;
    return true;
}

PHP_QT_API bool qt_qthreadruntime_worker_publish_zval(zend_string *event_name, zval *payload, std::string *error)
{
    if (!qt_qthreadruntime_event_name_valid(event_name)) {
        if (error != NULL) {
            *error = "event name must be non-empty";
        }
        return false;
    }

    zval payload_input;
    if (payload != NULL) {
        ZVAL_COPY(&payload_input, payload);
    } else {
        array_init(&payload_input);
    }

    qt_qthreadruntime_value payload_value;
    std::string payload_error;
    bool ok_payload = qt_qthreadruntime_zval_to_value(&payload_input, &payload_value, &payload_error);
    zval_ptr_dtor(&payload_input);
    if (!ok_payload) {
        if (error != NULL) {
            *error = payload_error;
        }
        return false;
    }

    std::string event(ZSTR_VAL(event_name), ZSTR_LEN(event_name));
    if (qt_qthreadruntime_tls_current_state != nullptr && qt_qthreadruntime_tls_current_job_id != 0) {
        return qt_qthreadruntime_tls_current_state->publishFromWorker(qt_qthreadruntime_tls_current_job_id, event, payload_value);
    }

    if (qt_qthreadruntime_tls_current_task_host != nullptr) {
        return qt_qthreadruntime_tls_current_task_host->publishFromWorker(event, payload_value);
    }

    if (error != NULL) {
        *error = "publish() can only be called from an active worker job context.";
    }
    return false;
}

PHP_QT_API bool qt_qthreadruntime_worker_receive_zval(zend_long timeout_ms, zval *return_value, bool *has_message, std::string *error)
{
    if (return_value == NULL || has_message == NULL) {
        if (error != NULL) {
            *error = "invalid receive target";
        }
        return false;
    }

    *has_message = false;
    qt_qthreadruntime_event_message message;
    bool received = false;

    if (qt_qthreadruntime_tls_current_state != nullptr && qt_qthreadruntime_tls_current_job_id != 0) {
        received = qt_qthreadruntime_tls_current_state->receiveForWorker(qt_qthreadruntime_tls_current_job_id, timeout_ms, &message);
    } else if (qt_qthreadruntime_tls_current_task_host != nullptr) {
        received = qt_qthreadruntime_tls_current_task_host->receiveForWorker(timeout_ms, &message);
    } else {
        if (error != NULL) {
            *error = "receive() can only be called from an active worker job context.";
        }
        return false;
    }

    if (!received) {
        *has_message = false;
        ZVAL_NULL(return_value);
        return true;
    }

    zval payload_value;
    if (!qt_qthreadruntime_value_to_zval(message.payload, &payload_value)) {
        if (error != NULL) {
            *error = "failed to materialize received payload";
        }
        return false;
    }

    array_init(return_value);
    add_assoc_stringl(return_value, "event", message.event_name.data(), message.event_name.size());
    add_assoc_zval(return_value, "payload", &payload_value);
    *has_message = true;
    return true;
}

PHP_QT_API bool qt_qthreadruntime_current_task_context(qt_qthread_task_host **host, uint64_t *task_token)
{
    if (host == NULL || task_token == NULL) {
        return false;
    }

    *host = qt_qthreadruntime_tls_current_task_host;
    *task_token = qt_qthreadruntime_tls_current_task_token;
    return qt_qthreadruntime_tls_current_task_host != nullptr && qt_qthreadruntime_tls_current_task_token != 0;
}

PHP_QT_API bool qt_qthreadruntime_worker_is_canceled(void)
{
    if (qt_qthreadruntime_tls_interrupted) {
        return true;
    }

    if (qt_qthreadruntime_tls_current_task_host != nullptr) {
        return qt_qthreadruntime_tls_current_task_host->workerIsCanceled();
    }

    return false;
}

PHP_QT_API bool qt_qthreadruntime_worker_publish_progress(zend_long value, zend_long minimum, zend_long maximum, zend_string *text, std::string *error)
{
    zval payload;
    array_init(&payload);
    add_assoc_long(&payload, "value", value);
    add_assoc_long(&payload, "minimum", minimum);
    add_assoc_long(&payload, "maximum", maximum);
    if (text != NULL) {
        add_assoc_stringl(&payload, "text", ZSTR_VAL(text), ZSTR_LEN(text));
    } else {
        add_assoc_string(&payload, "text", "");
    }

    zend_string *progress_event = zend_string_init_interned("progress", sizeof("progress") - 1, 0);
    bool ok = qt_qthreadruntime_worker_publish_zval(progress_event, &payload, error);
    zend_string_release(progress_event);
    zval_ptr_dtor(&payload);
    return ok;
}

