{
    return host != NULL && host->isFutureFinished(task_token);
}

PHP_QT_API bool qt_qthread_task_host_future_is_canceled(qt_qthread_task_host *host, uint64_t task_token)
{
    return host != NULL && host->isFutureCanceled(task_token);
}

