PHP_METHOD(Qt_Core_QThreadRuntime, send)
{
    zend_long job_id = 0;
    zend_string *event_name = NULL;
    zval *payload = NULL;

    ZEND_PARSE_PARAMETERS_START(2, 3)
        Z_PARAM_LONG(job_id)
